import * as React from "react";
import { Icon } from "@/registry/erbium/ui/icon";
import { NumberField as NumberFieldPrimitive } from "@base-ui/react/number-field";
import { useReducedMotion } from "motion/react";
import { FieldLabel } from "@/registry/erbium/ui/field";
import { TextMorph } from "@/registry/erbium/ui/text-morph";
import { cn } from "@/registry/erbium/lib/erbium-utils";

/** Reasons that mean the person typed the text, so it must show as typed. */
const typedReasons = new Set<NumberFieldPrimitive.Root.ChangeEventReason>([
  "input-change",
  "input-clear",
  "input-paste",
]);

/** Keys Base UI turns into a new value rather than an edit of the text. */
const stepKeys = new Set(["ArrowUp", "ArrowDown", "PageUp", "PageDown", "Home", "End"]);

interface Grouping {
  group: string;
  digits: string[];
  format: (digits: bigint) => string;
}

/** The locale's group separator and digits, and a formatter that groups whole numbers. */
const createGrouping = (
  locale: Intl.LocalesArgument,
  { notation, useGrouping }: Pick<Intl.NumberFormatOptions, "notation" | "useGrouping">,
): Grouping | null => {
  if (useGrouping === false || notation !== undefined) {
    return null;
  }

  const formatter = new Intl.NumberFormat(locale, {
    maximumFractionDigits: 0,
    useGrouping: useGrouping ?? true,
  });

  const group = formatter.formatToParts(1_234_567).find((part) => part.type === "group")?.value;

  if (group === undefined || group === "") {
    return null;
  }

  const digits = Array.from({ length: 10 }, (_, digit) => formatter.format(digit));

  return { digits, group, format: (value) => formatter.format(value) };
};

/**
 * Regroups the integer digits of typed text, the way Base UI would on blur, and
 * keeps the caret after the same digit. Prefixes, suffixes, and the fraction are
 * left as typed. Returns null when there is nothing to change.
 */
const regroup = (text: string, caret: number, grouping: Grouping) => {
  /** The digit's value in the locale's or ASCII digits, or -1 for any other character. */
  const digitOf = (character: string) => {
    const localeDigit = grouping.digits.indexOf(character);

    if (localeDigit !== -1) {
      return localeDigit;
    }

    return "0123456789".includes(character) ? Number(character) : -1;
  };

  // String indices, so `start` and `end` line up with `slice` below.
  let start = 0;

  while (start < text.length && digitOf(text.charAt(start)) === -1) {
    start += 1;
  }

  if (start === text.length) {
    return null;
  }

  let end = start;

  while (
    end < text.length &&
    (digitOf(text.charAt(end)) !== -1 || text.charAt(end) === grouping.group)
  ) {
    end += 1;
  }

  // Character-wise string ops rather than `Array.from`: spreading or
  // converting a string is flagged by typescript/no-misused-spread.
  const digits = text
    .slice(start, end)
    .replaceAll(grouping.group, "")
    .replaceAll(/./gu, (character) => `${digitOf(character)}`);

  // A leading zero is mid-edit ("0.5", "05"); grouping would swallow it.
  if (digits.length > 1 && digits.startsWith("0")) {
    return null;
  }

  const next = text.slice(0, start) + grouping.format(BigInt(digits)) + text.slice(end);

  if (next === text) {
    return null;
  }

  // Count of non-grouping characters before the caret.
  const kept = text.slice(0, caret).replaceAll(grouping.group, "").length;

  let position = 0;

  for (let count = 0; position < next.length && count < kept; position += 1) {
    if (next.charAt(position) !== grouping.group) {
      count += 1;
    }
  }

  return { caret: position, text: next };
};

interface NumberFieldContextValue {
  fieldId: string;
  /** True while the person edits the text; their edits never animate. */
  typing: boolean;
  setTyping: (typing: boolean) => void;
  /** Morph values that change by stepping, scrubbing, or from outside. */
  animated: boolean;
  grouping: Grouping | null;
}

const NumberFieldContext = React.createContext<NumberFieldContextValue | null>(null);

const useNumberFieldContext = (part: string) => {
  const context = React.useContext(NumberFieldContext);

  if (!context) {
    throw new Error(`${part} must be used within NumberField.`);
  }

  return context;
};

type NumberFieldProps = NumberFieldPrimitive.Root.Props & {
  size?: "sm" | "default" | "lg";
  animated?: boolean;
  /** Regroup digits as they are typed, instead of only once the field blurs. */
  groupWhileTyping?: boolean;
};

const NumberField = ({
  id,
  className,
  size = "default",
  animated = true,
  groupWhileTyping = true,
  format,
  locale,
  onValueChange,
  ...props
}: NumberFieldProps) => {
  const generatedId = React.useId();
  const fieldId = id ?? generatedId;
  const [typing, setTyping] = React.useState(false);
  // `format` is usually an inline object, so key the grouping on the two options it reads.
  const notation = format?.notation;
  const useGrouping = format?.useGrouping;

  const grouping = React.useMemo(
    () => (groupWhileTyping ? createGrouping(locale, { notation, useGrouping }) : null),
    [groupWhileTyping, locale, notation, useGrouping],
  );

  const context = React.useMemo(
    () => ({ animated, fieldId, grouping, setTyping, typing }),
    [fieldId, typing, animated, grouping],
  );

  return (
    <NumberFieldContext.Provider value={context}>
      <NumberFieldPrimitive.Root
        id={fieldId}
        data-slot="number-field"
        data-size={size}
        className={cn(
          "group/number-field flex w-full min-w-0 flex-col items-start gap-related",
          className,
        )}
        format={format}
        locale={locale}
        onValueChange={(value, details) => {
          setTyping(typedReasons.has(details.reason));
          onValueChange?.(value, details);
        }}
        {...props}
      />
    </NumberFieldContext.Provider>
  );
};

const NumberFieldGroup = ({ className, ...props }: NumberFieldPrimitive.Group.Props) => (
  <NumberFieldPrimitive.Group
    data-slot="number-field-group"
    className={cn(
      "relative flex min-h-control w-full min-w-0 items-stretch rounded-lg border surface-field text-field text-foreground tabular-nums transition-[color,background-color,box-shadow] duration-150 group-data-[size=lg]/number-field:min-h-control-lg group-data-[size=sm]/number-field:min-h-control-sm has-aria-invalid:border-error has-aria-invalid:ring-[1.5px] has-aria-invalid:ring-invalid-halo motion-reduce:transition-none dark:has-aria-invalid:border-invalid data-disabled:pointer-events-none data-disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
      className,
    )}
    {...props}
  />
);

const stepperClass =
  "relative flex shrink-0 cursor-pointer items-center justify-center px-2 text-muted-foreground transition-colors duration-150 outline-none group-data-[size=sm]/number-field:px-1.5 hover:bg-foreground/5 hover:text-foreground focus-visible:bg-foreground/5 data-disabled:pointer-events-none data-disabled:opacity-50 motion-reduce:transition-none touch-target";

const NumberFieldDecrement = ({
  className,
  children,
  ...props
}: NumberFieldPrimitive.Decrement.Props) => (
  <NumberFieldPrimitive.Decrement
    data-slot="number-field-decrement"
    className={cn(stepperClass, "rounded-s-[calc(var(--radius-lg)-1px)]", className)}
    {...props}
  >
    {children ?? <Icon name="minus-sign" aria-hidden />}
  </NumberFieldPrimitive.Decrement>
);

const NumberFieldIncrement = ({
  className,
  children,
  ...props
}: NumberFieldPrimitive.Increment.Props) => (
  <NumberFieldPrimitive.Increment
    data-slot="number-field-increment"
    className={cn(stepperClass, "rounded-e-[calc(var(--radius-lg)-1px)]", className)}
    {...props}
  >
    {children ?? <Icon name="plus-sign" aria-hidden />}
  </NumberFieldPrimitive.Increment>
);

const layerClass =
  "pointer-events-none absolute inset-0 content-center overflow-hidden px-2.5 whitespace-pre group-data-[size=sm]/number-field:px-2";

type NumberFieldInputProps = Omit<NumberFieldPrimitive.Input.Props, "className" | "render"> & {
  /** Styles the text box. Alignment and font reach both the input and its morph. */
  className?: string;
};

/**
 * An <input> places its text about a pixel off from the same text in any other
 * element, so the visible text is always drawn by these layers and the input
 * only supplies the caret, selection, and editing. Plain text shows at rest and
 * while typing; the morph layer takes over only while a value animates, where
 * its slightly different glyph spacing is lost in the motion.
 */
const NumberFieldInputLayers = ({
  inputProps,
  value,
  typing,
  composing,
  animated,
  className,
  textRef,
  morphRef,
}: {
  inputProps: React.ComponentPropsWithRef<"input">;
  value: string;
  typing: boolean;
  composing: boolean;
  animated: boolean;
  className?: string;
  textRef: React.Ref<HTMLSpanElement>;
  morphRef: React.Ref<HTMLSpanElement>;
}) => {
  const reducedMotion = useReducedMotion();
  const [shownValue, setShownValue] = React.useState(value);
  // The value being animated, or null at rest. Each new value restarts the fallback timer.
  const [morphingValue, setMorphingValue] = React.useState<string | null>(null);
  const morphing = morphingValue !== null;

  // Decided while rendering, so the plain layer never paints a new value first.
  if (value !== shownValue) {
    setShownValue(value);
    setMorphingValue(animated && reducedMotion !== true && !typing ? value : null);
  }

  React.useEffect(() => {
    // In case the morph never reports back, e.g. text torph left unanimated. Each value gets
    // its own timer, which clears only that value; at rest it is a no-op.
    const timeout = window.setTimeout(() => {
      setMorphingValue((current) => (current === morphingValue ? null : current));
    }, 1000);

    return () => {
      window.clearTimeout(timeout);
    };
  }, [morphingValue]);

  return (
    <span
      data-slot="number-field-input-wrapper"
      data-typing={typing || undefined}
      data-morphing={morphing || undefined}
      data-composing={composing || undefined}
      className={cn("group/number-field-input relative flex min-w-0 grow text-center", className)}
    >
      <span
        ref={textRef}
        aria-hidden="true"
        data-slot="number-field-text"
        className={cn(
          layerClass,
          "group-data-composing/number-field-input:invisible group-data-morphing/number-field-input:invisible",
        )}
      >
        {value}
      </span>
      <span
        ref={morphRef}
        aria-hidden="true"
        data-slot="number-field-display"
        className={cn(
          layerClass,
          "invisible group-data-composing/number-field-input:invisible group-data-morphing/number-field-input:visible",
        )}
      >
        <TextMorph
          disabled={!animated}
          onAnimationComplete={() => {
            setMorphingValue(null);
          }}
        >
          {value}
        </TextMorph>
      </span>
      <input
        {...inputProps}
        className={cn(
          // Composition text isn't in Base UI's value yet, so it shows natively.
          "relative size-full min-w-0 bg-transparent px-2.5 [text-align:inherit] text-transparent caret-foreground outline-none group-data-composing/number-field-input:text-foreground group-data-[size=sm]/number-field:px-2 selection:bg-ring/25 placeholder:text-muted-foreground",
          inputProps.className,
        )}
      />
    </span>
  );
};

const NumberFieldInput = ({
  className,
  onBlur,
  onChange,
  onCompositionEnd,
  onCompositionStart,
  onKeyDown,
  onPointerDown,
  onScroll,
  ...props
}: NumberFieldInputProps) => {
  const { typing, setTyping, animated, grouping } = useNumberFieldContext("NumberFieldInput");
  const [composing, setComposing] = React.useState(false);
  const textRef = React.useRef<HTMLSpanElement>(null);
  const morphRef = React.useRef<HTMLSpanElement>(null);

  return (
    <NumberFieldPrimitive.Input
      data-slot="number-field-input"
      onChange={(event) => {
        // Runs before Base UI's own handler, which then reads the regrouped text.
        const input = event.currentTarget;
        const { nativeEvent } = event;
        const isComposing = nativeEvent instanceof InputEvent && nativeEvent.isComposing;

        const next =
          grouping && !isComposing && input.selectionStart !== null
            ? regroup(input.value, input.selectionStart, grouping)
            : null;

        if (next) {
          input.value = next.text;
          input.setSelectionRange(next.caret, next.caret);
        }

        // Also covers partial text, like a lone "-", that Base UI can't parse yet.
        setTyping(true);
        onChange?.(event);
      }}
      onPointerDown={(event) => {
        // Placing the caret or selecting needs the real glyphs under the pointer.
        setTyping(true);
        onPointerDown?.(event);
      }}
      onKeyDown={(event) => {
        setTyping(!stepKeys.has(event.key));
        onKeyDown?.(event);
      }}
      onBlur={(event) => {
        setTyping(false);
        onBlur?.(event);
      }}
      onCompositionStart={(event) => {
        setComposing(true);
        onCompositionStart?.(event);
      }}
      onCompositionEnd={(event) => {
        setComposing(false);
        onCompositionEnd?.(event);
      }}
      onScroll={(event) => {
        // Each layer is its own clipped scroller; mirroring keeps it on the caret.
        for (const layer of [textRef.current, morphRef.current]) {
          if (layer) {
            layer.scrollLeft = event.currentTarget.scrollLeft;
          }
        }

        onScroll?.(event);
      }}
      render={(inputProps, state) => (
        <NumberFieldInputLayers
          inputProps={inputProps}
          value={state.inputValue}
          typing={typing}
          composing={composing}
          animated={animated}
          className={className}
          textRef={textRef}
          morphRef={morphRef}
        />
      )}
      {...props}
    />
  );
};

const NumberFieldScrubArea = ({
  className,
  label,
  ...props
}: NumberFieldPrimitive.ScrubArea.Props & { label: string }) => {
  const { fieldId } = useNumberFieldContext("NumberFieldScrubArea");

  return (
    <NumberFieldPrimitive.ScrubArea
      data-slot="number-field-scrub-area"
      className={cn("flex cursor-ew-resize", className)}
      {...props}
    >
      <FieldLabel htmlFor={fieldId} className="cursor-ew-resize">
        {label}
      </FieldLabel>
      <NumberFieldPrimitive.ScrubAreaCursor className="drop-shadow-[0_1px_1px_var(--cursor-shadow)]">
        <svg
          aria-hidden="true"
          width="26"
          height="14"
          viewBox="0 0 24 14"
          fill="var(--color-cursor-fill)"
          stroke="var(--color-cursor-stroke)"
        >
          <path d="M19.5 5.5L6.5 5.52V2L1 7L6.5 12L6.5 8.5L19.5 8.5V12L25 7L19.5 2V5.5Z" />
        </svg>
      </NumberFieldPrimitive.ScrubAreaCursor>
    </NumberFieldPrimitive.ScrubArea>
  );
};

export {
  NumberField,
  NumberFieldDecrement,
  NumberFieldGroup,
  NumberFieldIncrement,
  NumberFieldInput,
  NumberFieldScrubArea,
};

export type { NumberFieldInputProps, NumberFieldProps };
